            weight += occ[i]
    return float(total / weight) if weight > 0 else 0.0"},{"description":"First-shell squared electronegativity contrast weighted by inverse distance, summed per occupied atom with directed-pair correction.","name":"contact_electronegativity_mismatch","source":"def feature(s):
