    fractions = [x for x in s.get('composition', {}).values() if x is not None and x > 0 and math.isfinite(x)]
    norm = sum(fractions)
    if total <= 0 or norm <= 0:
        return 0.0
    random_unlike = 1.0 - sum((x / norm) ** 2 for x in fractions)
    return float(unlike / total - random_unlike)"},{"description":"Mean electronegativity variance among the neighbors of each site, measuring ligand-environment chemical diversity.","name":"neighbor_electronegativity_variance","source":"def feature(s):
