            weight += occ[i]
    return float(total / weight) if weight > 0 else 0.0"},{"description":"Fraction of first-shell contacts joining identical elements with Pauling electronegativity at least 2.5; sensitive to anion-like molecular bonds.","name":"electronegative_homonuclear_contact_fraction","source":"def feature(s):
